```css
@font-face {
    font-family: mylove;
    src: url(MyLove.otf);
}

@font-face {
    font-family: gob;
    src: url(gob.otf);
}

html, body {
    height: 100vh;
    margin: 0;
}

body {
    background-image: url(aaaa.jpg);
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
}

#title {
    color: lightsalmon;
    font-family: mylove, cursive, sans-serif;
    font-size: 100px;
    margin: 50px 0 20px 0;
    letter-spacing: 2px;
}

#text {
    font-family: gob, sans-serif;
    font-size: 30px;
    margin-bottom: auto;
    color: bisque;
}

#top-section {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 50px;
    gap: 40px;
}

#btn {
    padding: 15px 100px;
    font-size: 32px;
    border: 2px solid rgba(0, 0, 0, 0.2);
    font-family: gob, sans-serif;
    margin-top: 20px;
    border-radius: 12px;
    background-color: rgba(0, 0, 0, 0.3);
    color: rgba(222, 150, 236, 0.5);
    position: relative;
    cursor: pointer;
    overflow: hidden;
    transition: background 0.3s;
}

#btn::before {
    content: '';
    display: block;
    width: 0;
    left: 0;
    bottom: 0;
    height: 2px;
    position: absolute;
    background: white;
    transition: width 1s ease-out;
}

#btn:hover {
    background-color: rgba(0, 0, 0, 0.5);
    color: rgba(212, 140, 236, 0.92);
}

#btn:hover::before {
    width: 100%;
}

#answers, #question {
    font-family: gob, sans-serif;
    font-size: 30px;
    color: rgba(255, 66, 3, 0.4);
    white-space: pre-wrap;
}

#question_box, #answers_box {
    background-color: rgba(0, 0, 0, 0.2);
    border: 2px solid rgb(8, 71, 153);
    border-radius: 12px;
    max-width: 500px;
    width: 80%;
    max-height: 200px;
    overflow-y: auto;
    margin-top: 40px;
    padding: 20px;
    text-align: center;
    transition: box-shadow 0.3s, background 2s ease-in;
    align-self: center;
}

#question_box:hover, #answers_box:hover {
    box-shadow: 0 4px 24px rgba(8, 71, 153, 0.2);
    background-color: rgba(0, 0, 0, 0.3);
}
```

```py
def find_min():
    crops = [Entities.Grass, Entities.Bush, Entities.Carrot, Entities.Sunflower, Entities.Pumpkin]
    count = [num_items(Items.Hay), num_items(Items.Wood), num_items(Items.Carrot), num_items(Items.Power), num_items(Items.Pumpkin)]

    lowest = count[0]
    index = 0 

    for i in range(len(count)):
        if lowest >= count[i]:
            lowest = count[i]
            index = i

    return crops[index]

def water():
    if get_water() < 1:
        use_item(Items.Water)

def pumpkins():
    while True:
            h = 0
            for i in range(get_world_size()):
                for j in range(get_world_size()):
                    if can_harvest():
                        h += 1
                water()
                plant(Entities.Pumpkin)
                move(North)
            move(East)


            if h == get_world_size() ** 2 :
                for i in range(get_world_size()):
                    for j in range(get_world_size()):
                        if can_harvest():
                            harvest()
                    water()
                    plant(Entities.Pumpkin)
                    move(North)
                move(East)
                h = 0

                if Items.Carrot == 0:
                    crop(Entities.Carrot)
                else:
                    pumpkins()


def crop(entity):
    for i in range(get_world_size()):
        for j in range(get_world_size()):
            if can_harvest():
                harvest()
        water()
        plant(entity)
        move(North)
    move(East)


while True:
    crop_name = find_min()
    crop(crop_name)
```

```py

def water():
    if get_water() < 0.2:
        use_item(Items.Water)

def crop(entity):
    for i in range(get_world_size()):
        for j in range(get_world_size()):
            harvest()
            water()
            plant(entity)
            move(North)
        move(East)

while True:
    if num_items(Items.Wood) < 500:
        crop(Entities.Bush)

    elif num_items(Items.Hay) < 500:
        crop(Entities.Grass)

    elif num_items(Items.Wood) >= 500:
        crop(Entities.Carrot)

    elif num_items(Items.Carrot) > 700:
        crop(Entities.Grass)
